window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c1a8f4ca8cf1f1c"]={"versions": [{"id": "FIG-1c1a8f4ca8cf1f1c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der Sende-Bestätigung (Transmit Confirmation) mit Pufferung (Transmit Buffering) innerhalb des AUTOSAR Classic Platform CAN-Stacks (Communication Hardware Abstraction Layer). Das Diagramm bildet die Interaktion zwischen CAN-Hardware-Peripherie, CAN-Treiber (MCAL), CAN-Interface (CanIf), Schedule Manager (SchM) und übergeordneten CanIf-Benutzern (z. B. PduR, CanNm, CanTp) ab.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Übergeordnete Schicht bzw. Software-Modul (z. B. PDU Router).\n</li><li><code>«module» SchM</code>: BSW-Scheduler / Basic Software Mode Manager (im Sequenzablauf als passive Lifeline ohne expliziten Nachrichtenfluss dargestellt).\n</li><li><code>«module» CanIf</code>: CAN Interface zur Abstraktion der Hardware-Details und Pufferverwaltung.\n</li><li><code>«module» Can</code>: CAN-Treiber (MCAL) mit Treiber-Lebenslinie.\n</li><li><code>«Peripheral» CanController</code>: Hardware-Peripherie des CAN-Controllers.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>Transmit Confirmation Interrupt()</code>: Hardware-Interrupt der CAN-Peripherie an den CAN-Treiber.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Aufruf des CanIf durch den CAN-Treiber zur Weitergabe der Bestätigung für eine übertragene PDU.\n</li><li><code>check transmit buffers for other pending L-PDU()</code>: Interne CanIf-Prüfoperation zur Ermittlung anstehender Sendeanforderungen.\n</li><li><code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: MCAL-Funktionsaufruf zur Initiierung eines neuen Sendeauftrags an den CAN-Treiber.\n</li><li><code>Write L-PDU into CAN Hardware()</code>: Hardware-Zugriff des CAN-Treibers auf den CAN-Controller.\n</li><li><code>Remove L-PDU successfully requested for transmission from transmit buffer()</code>: Interne CanIf-Operation zur Freigabe des Puffereintrags.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType)</code>: Konfigurierbare Bestätigungs-Callback-Funktion an das übergeordnete Modul (CanIf-User).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Auslösung: Der <code>CanController</code> signalisiert einen erfolgreichen Sendevorgang via <code>Transmit Confirmation Interrupt()</code> an das MCAL-Modul <code>Can</code>.\n</li><li>Treiber-Rückmeldung: Das Modul <code>Can</code> ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am <code>CanIf</code> auf.\n</li><li>Pufferprüfung: <code>CanIf</code> führt einen internen Aufruf <code>check transmit buffers for other pending L-PDU()</code> durch.\n</li><li>Bedingter Zweig (<code>alt Transmit Buffering</code>):\n<ul class=\"fig-list\"><li>Fall <code>[Buffer is filled]</code>:\n<ul class=\"fig-list\"><li><code>CanIf</code> ruft <code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code> am CAN-Treiber auf.\n</li><li><code>Can</code> schreibt die L-PDU synchron über <code>Write L-PDU into CAN Hardware()</code> in den <code>CanController</code>.\n</li><li>Der Hardware-Zugriff kehrt mit <code>Write L-PDU into CAN Hardware()</code> zurück.\n</li><li><code>Can_Write()</code> kehrt zum <code>CanIf</code> zurück.\n</li><li><code>CanIf</code> entfernt die erfolgreich angeforderte L-PDU über <code>Remove L-PDU successfully requested for transmission from transmit buffer()</code>.\n</li></ul>\n</li><li>Fall <code>[Buffer is empty]</code>:\n<ul class=\"fig-list\"><li>Es erfolgt keine weitere Sendeanforderung an den Treiber.\n</li></ul>\n</li></ul>\n</li><li>Bestätigung an Benutzer: <code>CanIf</code> benachrichtigt den <code>CanIf User</code> synchron über <code>&lt;User_TxConfirmation&gt;(PduIdType)</code>, welche mit <code>&lt;User_TxConfirmation&gt;()</code> zurückkehrt.\n</li><li>Abschluss: <code>CanIf_TxConfirmation()</code> kehrt zum Modul <code>Can</code> zurück, welches die Interrupt-Behandlung mit Rückkehr von <code>Transmit Confirmation Interrupt()</code> an den <code>CanController</code> beendet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Relevanz für die Implementierung der CanIf-Sendepufferung: Zeigt das Entleeren ausstehender Sende-PDUs im Kontext der Sende-Bestätigung (Priority Inversion Avoidance bzw. FIFO/Prioritätsabarbeitung).\n</li><li>Ausführungskontext: Der gesamte Bestätigungs- und Pufferleerungsprozess wird synchron im Interrupt-Kontext (<code>Transmit Confirmation Interrupt</code>) ausgeführt, sofern kein Polling konfiguriert ist.\n</li><li>Pufferkonsistenz: Eine PDU wird erst nach erfolgreichem Rückgabewert von <code>Can_Write()</code> aus dem internen Sendepuffer entfernt (<code>Remove L-PDU successfully requested for transmission from transmit buffer()</code>).\n</li><li>SchM-Rolle: Die Lifeline <code>SchM</code> verdeutlicht, dass Pufferprüfungen und Pufferzugriffe bei nebenläufigen Task- und Interrupt-Kontexten durch entsprechende SchM-Kritische Bereiche geschützt werden müssen, auch wenn keine direkten Nachrichtenpfeile eingezeichnet sind.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-75cde11203f5228f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der Sende-Bestätigung (Transmit Confirmation) mit Pufferung (Transmit Buffering) innerhalb des AUTOSAR Classic Platform CAN-Stacks (Communication Hardware Abstraction Layer). Das Diagramm bildet die Interaktion zwischen CAN-Hardware-Peripherie, CAN-Treiber (MCAL), CAN-Interface (CanIf), Schedule Manager (SchM) und übergeordneten CanIf-Benutzern (z. B. PduR, CanNm, CanTp) ab.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Übergeordnete Schicht bzw. Software-Modul (z. B. PDU Router).\n</li><li><code>«module» SchM</code>: BSW-Scheduler / Basic Software Mode Manager (im Sequenzablauf als passive Lifeline ohne expliziten Nachrichtenfluss dargestellt).\n</li><li><code>«module» CanIf</code>: CAN Interface zur Abstraktion der Hardware-Details und Pufferverwaltung.\n</li><li><code>«module» Can</code>: CAN-Treiber (MCAL) mit Treiber-Lebenslinie.\n</li><li><code>«Peripheral» CanController</code>: Hardware-Peripherie des CAN-Controllers.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>Transmit Confirmation Interrupt()</code>: Hardware-Interrupt der CAN-Peripherie an den CAN-Treiber.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Aufruf des CanIf durch den CAN-Treiber zur Weitergabe der Bestätigung für eine übertragene PDU.\n</li><li><code>check transmit buffers for other pending L-PDU()</code>: Interne CanIf-Prüfoperation zur Ermittlung anstehender Sendeanforderungen.\n</li><li><code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: MCAL-Funktionsaufruf zur Initiierung eines neuen Sendeauftrags an den CAN-Treiber.\n</li><li><code>Write L-PDU into CAN Hardware()</code>: Hardware-Zugriff des CAN-Treibers auf den CAN-Controller.\n</li><li><code>Remove L-PDU successfully requested for transmission from transmit buffer()</code>: Interne CanIf-Operation zur Freigabe des Puffereintrags.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType)</code>: Konfigurierbare Bestätigungs-Callback-Funktion an das übergeordnete Modul (CanIf-User).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Auslösung: Der <code>CanController</code> signalisiert einen erfolgreichen Sendevorgang via <code>Transmit Confirmation Interrupt()</code> an das MCAL-Modul <code>Can</code>.\n</li><li>Treiber-Rückmeldung: Das Modul <code>Can</code> ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am <code>CanIf</code> auf.\n</li><li>Pufferprüfung: <code>CanIf</code> führt einen internen Aufruf <code>check transmit buffers for other pending L-PDU()</code> durch.\n</li><li>Bedingter Zweig (<code>alt Transmit Buffering</code>):\n<ul class=\"fig-list\"><li>Fall <code>[Buffer is filled]</code>:\n<ul class=\"fig-list\"><li><code>CanIf</code> ruft <code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code> am CAN-Treiber auf.\n</li><li><code>Can</code> schreibt die L-PDU synchron über <code>Write L-PDU into CAN Hardware()</code> in den <code>CanController</code>.\n</li><li>Der Hardware-Zugriff kehrt mit <code>Write L-PDU into CAN Hardware()</code> zurück.\n</li><li><code>Can_Write()</code> kehrt zum <code>CanIf</code> zurück.\n</li><li><code>CanIf</code> entfernt die erfolgreich angeforderte L-PDU über <code>Remove L-PDU successfully requested for transmission from transmit buffer()</code>.\n</li></ul>\n</li><li>Fall <code>[Buffer is empty]</code>:\n<ul class=\"fig-list\"><li>Es erfolgt keine weitere Sendeanforderung an den Treiber.\n</li></ul>\n</li></ul>\n</li><li>Bestätigung an Benutzer: <code>CanIf</code> benachrichtigt den <code>CanIf User</code> synchron über <code>&lt;User_TxConfirmation&gt;(PduIdType)</code>, welche mit <code>&lt;User_TxConfirmation&gt;()</code> zurückkehrt.\n</li><li>Abschluss: <code>CanIf_TxConfirmation()</code> kehrt zum Modul <code>Can</code> zurück, welches die Interrupt-Behandlung mit Rückkehr von <code>Transmit Confirmation Interrupt()</code> an den <code>CanController</code> beendet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Relevanz für die Implementierung der CanIf-Sendepufferung: Zeigt das Entleeren ausstehender Sende-PDUs im Kontext der Sende-Bestätigung (Priority Inversion Avoidance bzw. FIFO/Prioritätsabarbeitung).\n</li><li>Ausführungskontext: Der gesamte Bestätigungs- und Pufferleerungsprozess wird synchron im Interrupt-Kontext (<code>Transmit Confirmation Interrupt</code>) ausgeführt, sofern kein Polling konfiguriert ist.\n</li><li>Pufferkonsistenz: Eine PDU wird erst nach erfolgreichem Rückgabewert von <code>Can_Write()</code> aus dem internen Sendepuffer entfernt (<code>Remove L-PDU successfully requested for transmission from transmit buffer()</code>).\n</li><li>SchM-Rolle: Die Lifeline <code>SchM</code> verdeutlicht, dass Pufferprüfungen und Pufferzugriffe bei nebenläufigen Task- und Interrupt-Kontexten durch entsprechende SchM-Kritische Bereiche geschützt werden müssen, auch wenn keine direkten Nachrichtenpfeile eingezeichnet sind.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1c1a8f4ca8cf1f1c", "to": "FIG-75cde11203f5228f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammüberschrift: Die im Diagrammbild oben links platzierte Textzeile „9.5 Transmit confirmation (with buffering)“ wurde entfernt.\n</li><li>Typografie: Bei <code>Can_Write(Can_ReturnType, ...)</code> wurde „Can_ReturnType“ zu „Can_ReturnType“ verschrieben.\n</li></ul>"}]};
